import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"Requirements for Laravel SaaS Starter Kits","description":"What you need to run a SaaS Laravel starter kit: PHP 8.3+, Composer 2, Node.js LTS, MySQL for per-tenant databases and a local server with wildcard subdomains.","frontmatter":{"title":"Requirements for Laravel SaaS Starter Kits","description":"What you need to run a SaaS Laravel starter kit: PHP 8.3+, Composer 2, Node.js LTS, MySQL for per-tenant databases and a local server with wildcard subdomains.","head":[["link",{"rel":"canonical","href":"https://saas-laravel.com/docs/getting-started/requirements.html"}],["meta",{"property":"og:title","content":"Requirements for Laravel SaaS Starter Kits"}],["meta",{"property":"og:description","content":"What you need to run a SaaS Laravel starter kit: PHP 8.3+, Composer 2, Node.js LTS, MySQL for per-tenant databases and a local server with wildcard subdomains."}],["meta",{"property":"og:url","content":"https://saas-laravel.com/docs/getting-started/requirements.html"}],["meta",{"name":"twitter:title","content":"Requirements for Laravel SaaS Starter Kits"}],["meta",{"name":"twitter:description","content":"What you need to run a SaaS Laravel starter kit: PHP 8.3+, Composer 2, Node.js LTS, MySQL for per-tenant databases and a local server with wildcard subdomains."}]]},"headers":[],"relativePath":"docs/getting-started/requirements.md","filePath":"docs/getting-started/requirements.md","lastUpdated":1790486087000}'),s={name:"docs/getting-started/requirements.md"};function o(n,t,i,c,l,p){return a(),r("div",null,[...t[0]||(t[0]=[d(`<h1 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Tool</th><th>Version</th><th>Notes</th></tr></thead><tbody><tr><td>PHP</td><td><code>^8.3</code></td><td>The kits are developed and tested on PHP 8.4. Extensions required by Laravel 13, plus <code>pdo_mysql</code>.</td></tr><tr><td>Composer</td><td>2.x</td><td>Installs the Laravel backend.</td></tr><tr><td>Node.js + npm</td><td>A current Node LTS</td><td><code>@erag/lang-sync-inertia</code> declares <code>node &gt;= 24</code>. Each kit ships a <code>package-lock.json</code>, so use <strong>npm</strong>.</td></tr><tr><td>MySQL (or MariaDB)</td><td>Any supported version</td><td>Multi-database tenancy creates one database per tenant, so the DB user must be allowed to <code>CREATE DATABASE</code> / <code>DROP DATABASE</code>.</td></tr><tr><td>Local web server with wildcard subdomains</td><td>—</td><td><a href="https://herd.laravel.com" target="_blank" rel="noreferrer">Laravel Herd</a> is recommended.</td></tr><tr><td>Git</td><td>—</td><td>To clone your kit repository and pull updates.</td></tr></tbody></table><h2 id="why-herd" tabindex="-1">Why Herd <a class="header-anchor" href="#why-herd" aria-label="Permalink to &quot;Why Herd&quot;">​</a></h2><p>Tenants are identified by domain, so every tenant subdomain must reach your app:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>APP_DOMAIN=vue.test</span></span>
<span class="line"><span>vue.test        → central app</span></span>
<span class="line"><span>acme.vue.test   → tenant created with the subdomain &quot;acme&quot;</span></span></code></pre></div><p>Herd serves <code>*.test</code> sites and their subdomains out of the box, so every new tenant works without extra DNS or hosts-file entries.</p><div class="tip custom-block"><p class="custom-block-title">Other setups</p><p>Any local stack works as long as the central domain <strong>and all of its subdomains</strong> point to the project&#39;s <code>public/</code> directory without a port in the URL (tenant links are built as <code>scheme://&lt;domain&gt;/path</code>). Laravel Sail is installed as a dev dependency, but the kits are configured and tested with Herd.</p></div><h2 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h2><p><code>.env.example</code> uses <code>DB_CONNECTION=mysql</code>. <code>config/tenancy.php</code> also registers database managers for <code>sqlite</code>, <code>mariadb</code> and <code>pgsql</code>, but MySQL is the setup the kits are built and tested against.</p><div class="warning custom-block"><p class="custom-block-title">Database permissions</p><p>Creating a tenant runs <code>CREATE DATABASE</code> on the central connection. If your DB user cannot create databases, tenant creation fails.</p></div><h2 id="production" tabindex="-1">Production <a class="header-anchor" href="#production" aria-label="Permalink to &quot;Production&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Why</th></tr></thead><tbody><tr><td>PHP <code>^8.3</code></td><td>Same as local</td></tr><tr><td>Web server routing the central domain and a wildcard subdomain (<code>*.your-domain.com</code>) to the app, plus a wildcard DNS record</td><td>Every tenant is a subdomain</td></tr><tr><td>A database user with rights to create tenant databases</td><td>Tenant creation runs <code>CREATE DATABASE</code></td></tr><tr><td>A queue worker (<code>php artisan queue:work</code>)</td><td>Invitation and password-reset emails are queued</td></tr><tr><td>A real mailer (<code>MAIL_MAILER=smtp</code> or similar)</td><td>So those emails are delivered</td></tr></tbody></table><p>Next: <a href="/docs/getting-started/installation.html">Installation</a>.</p>`,13)])])}const m=e(s,[["render",o]]);export{h as __pageData,m as default};
